using System;using System.Linq;using System.Collections.Generic;using System.Text.Json;using Evaluator;class Program{static void Main(){System.Globalization.CultureInfo.CurrentCulture=System.Globalization.CultureInfo.GetCultureInfo("en-US");var headers=new List<object>();foreach(var head in new[]{false,true})foreach(var total in new[]{false,true}){var h=new UIHandler();h.evaluatorsettings.ShowHeaders=head;h.evaluatorsettings.ShowTotal=total;h.OpenHTMLTable(true);h.AddHTMLTableHeaders(123456);headers.Add(new{head,total,html=h.currentPage.ToString()});}var systems=new List<object>();foreach(var filter in new[]{UIFilter.Default,UIFilter.MappingOnly,UIFilter.All})foreach(var current in new[]{false,true}){var h=new UIHandler();h.AddHTMLSystemDetails("Oracle",123456,654321,12,7,filter,current);systems.Add(new{filter=(int)filter,current,html=h.currentPage.ToString()});}var rows=new List<object>();for(int mask=0;mask<256;mask++)foreach(var checkbox in new[]{false,true}){var q=new OutputLine{Body="A 1",BodyID=9,ID64=18446744073709551614,IsStar=(mask&1)!=0,IsLandable=(mask&2)!=0,Map=(mask&4)!=0,Done=(mask&8)!=0,IsNextToVisit=(mask&16)!=0,WasDiscovered=(mask&32)!=0,WasMapped=(mask&64)!=0,WasFootfalled=(mask&128)!=0,Terraformable=true,Type=(mask&1)!=0?"G":"Earthlike body",Distance=12345.6,Gravity=new[]{0.0,0.12,0.51,1.2,2.4}[mask%5],Volcanism="Water geysers",CurrentValue=12345,PotentialMaxValue=987654,Order=(mask&4)!=0?3:0,Extra=new BodyExtra{BioCount=2,GeoCount=1,IsHighValue=true,BioInsightsHighValue=true,BioInsightsPersonalCodex=true,BioInsightsGalacticCodex=true,BioInsightsMarked=true,PluginWorthVisiting=true}};var h=new UIHandler();h.AddHTMLBodyDetails(q,"row1",checkbox);rows.Add(new{mask,checkbox,q,html=h.currentPage.ToString()});}var about=new UIHandler();about.GenerateAboutPage();var unsold=new List<object>();for(int n=0;n<5;n++){var lines=new List<(string name,DateTime dt,long value)>();if(n>0)lines.Add(("Alpha",new DateTime(2020,1,2,3,4,0,DateTimeKind.Utc),12345));if(n>1)lines.Add(("Repeat",new DateTime(2020,2,3,4,5,0,DateTimeKind.Utc),2000000000));if(n>2)lines.Add(("Repeat",new DateTime(2020,3,4,5,6,0,DateTimeKind.Utc),3000000000));if(n>3)lines.Add(("Last",new DateTime(2020,4,5,6,7,0,DateTimeKind.Utc),-12345));var h=new UIHandler();h.GenerateUnsoldDataPage(lines);unsold.Add(new{lines=lines.Select(l=>new object[]{l.name,l.dt.ToString("o"),l.value}).ToArray(),html=h.currentPage.ToString()});}Console.Write(JsonSerializer.Serialize(new{headers,systems,rows,about=about.currentPage.ToString(),unsold}));}}